import{_ as s,o as n,c as e,ae as i}from"./chunks/framework.Co1PSFSm.js";const k=JSON.parse('{"title":"Guard Mode","description":"","frontmatter":{},"headers":[],"relativePath":"guide/guard.md","filePath":"guide/guard.md"}'),t={name:"guide/guard.md"};function p(l,a,c,d,o,h){return n(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="guard-mode" tabindex="-1">Guard Mode <a class="header-anchor" href="#guard-mode" aria-label="Permalink to &quot;Guard Mode&quot;">​</a></h1><p>The <strong>guard mode</strong> is a pre-install safety check that validates packages before <code>npm install</code>, <code>npm i</code>, or <code>npm add</code> runs. It intercepts the command, checks each package against the npm registry and OSV database, and blocks the install if any issues are found — prompting the user to confirm or cancel.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>User: npm install lodash@^4.0.0</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼  (shell function intercepts)</span></span>
<span class="line"><span>    guard-npm.sh</span></span>
<span class="line"><span>        │  extracts package names: [&quot;lodash@^4.0.0&quot;]</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼  calls</span></span>
<span class="line"><span>    npx tsx src/guard.ts lodash@^4.0.0</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├─ NpmHttpClient.fetchMetadata()  → exists? 404?</span></span>
<span class="line"><span>        ├─ isPackageTooNew()              → &lt;72h?</span></span>
<span class="line"><span>        └─ OsvHttpClient.queryBatch()     → vulns? MAL-*?</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼  prints verdict per package</span></span>
<span class="line"><span>   ┌─ All clean → exit 0 → npm proceeds</span></span>
<span class="line"><span>   └─ Issues found → print report</span></span>
<span class="line"><span>                      ├─ &quot;y&quot; → exit 0 → npm proceeds</span></span>
<span class="line"><span>                      └─ &quot;n&quot; → exit 1 → npm is blocked</span></span></code></pre></div><h2 id="one-time-setup" tabindex="-1">One-time setup <a class="header-anchor" href="#one-time-setup" aria-label="Permalink to &quot;One-time setup&quot;">​</a></h2><p>Add the shell interceptor to your <code>.bashrc</code> or <code>.zshrc</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;">export</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;"> SENTINEL_DIR</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">=</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">&quot;/path/to/sentinel-ai&quot;</span></span>
<span class="line"><span style="--shiki-light:#D20F39;--shiki-light-font-style:italic;--shiki-dark:#F38BA8;--shiki-dark-font-style:italic;">source</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> &quot;</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">$SENTINEL_DIR</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">/scripts/guard-npm.sh&quot;</span></span></code></pre></div><p>Then reload your shell:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D20F39;--shiki-light-font-style:italic;--shiki-dark:#F38BA8;--shiki-dark-font-style:italic;">source</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ~/.bashrc</span><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;">   # or ~/.zshrc</span></span></code></pre></div><h2 id="using-directly" tabindex="-1">Using directly <a class="header-anchor" href="#using-directly" aria-label="Permalink to &quot;Using directly&quot;">​</a></h2><p>You can also run the guard check manually without the interceptor:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">npx</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> tsx</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> src/guard.ts</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> lodash</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> react</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">npx</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> tsx</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> src/guard.ts</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ai-slopsquatting</span><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;">        # hallucinated → blocked</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">npm</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> run</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> guard</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> lodash</span><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;">                          # via package script</span></span></code></pre></div><h2 id="scenarios" tabindex="-1">Scenarios <a class="header-anchor" href="#scenarios" aria-label="Permalink to &quot;Scenarios&quot;">​</a></h2><h3 id="all-packages-clean" tabindex="-1">All packages clean <a class="header-anchor" href="#all-packages-clean" aria-label="Permalink to &quot;All packages clean&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>$ npm install fast-glob</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sentinel guard — checking 1 package</span></span>
<span class="line"><span></span></span>
<span class="line"><span> ✓ fast-glob  v3.3.3</span></span>
<span class="line"><span></span></span>
<span class="line"><span> ✓ All packages look safe — proceeding with install.</span></span></code></pre></div><p>npm proceeds normally.</p><h3 id="hallucinated-blocked-package" tabindex="-1">Hallucinated / blocked package <a class="header-anchor" href="#hallucinated-blocked-package" aria-label="Permalink to &quot;Hallucinated / blocked package&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>$ npm install ai-slopsquatting</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sentinel guard — checking 1 package</span></span>
<span class="line"><span></span></span>
<span class="line"><span> ✗ ai-slopsquatting  → NOT FOUND on npm (hallucinated package)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>┌──────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  Blocked — 1 package has issues                  │</span></span>
<span class="line"><span>│  Review the warnings above before proceeding.    │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Install anyway? [y/N]</span></span></code></pre></div><p>Type <code>y</code> to override and allow the install, or press Enter (default <code>N</code>) to cancel.</p><h3 id="mixed-packages" tabindex="-1">Mixed packages <a class="header-anchor" href="#mixed-packages" aria-label="Permalink to &quot;Mixed packages&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>$ npm install lodash ai-slopsquatting</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sentinel guard — checking 2 packages</span></span>
<span class="line"><span></span></span>
<span class="line"><span> ✓ lodash            v4.18.1</span></span>
<span class="line"><span> ✗ ai-slopsquatting  → NOT FOUND on npm (hallucinated package)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>┌──────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  Blocked — 1 package has issues                  │</span></span>
<span class="line"><span>│  Review the warnings above before proceeding.    │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Install anyway? [y/N]</span></span></code></pre></div><p>All packages are checked and displayed. Only the problematic ones are flagged.</p><h2 id="what-is-checked" tabindex="-1">What is checked <a class="header-anchor" href="#what-is-checked" aria-label="Permalink to &quot;What is checked&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>Source</th><th>Blocks?</th></tr></thead><tbody><tr><td>Package exists on npm</td><td>npm registry (404 = hallucination)</td><td>Yes</td></tr><tr><td>Published &lt;72h ago</td><td>npm registry <code>time.created</code></td><td>Yes</td></tr><tr><td>Known vulnerabilities</td><td>OSV API batch query</td><td>Yes</td></tr><tr><td>MAL-* malware entries</td><td>OSV API (confirmed malware)</td><td>Yes</td></tr><tr><td>Node.js built-in module</td><td>Local set (<code>fs</code>, <code>path</code>, etc.)</td><td>No (skipped)</td></tr></tbody></table><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Exit code</th><th>Meaning</th></tr></thead><tbody><tr><td>0</td><td>All packages clean, or user chose to proceed</td></tr><tr><td>1</td><td>Issues found and user declined, or error</td></tr></tbody></table>`,26)])])}const u=s(t,[["render",p]]);export{k as __pageData,u as default};
